import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CiQ1TEvV.js";const p=JSON.parse('{"title":"Safety by Design","description":"","frontmatter":{},"headers":[],"relativePath":"features/safety.md","filePath":"features/safety.md","lastUpdated":1785115728000}'),i={name:"features/safety.md"};function r(o,e,d,c,l,u){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="safety-by-design" tabindex="-1">Safety by Design <a class="header-anchor" href="#safety-by-design" aria-label="Permalink to &quot;Safety by Design&quot;">​</a></h1><p>Mneme centralizes policy in <code>src/security.py</code>, so the CLI, TUI, query decomposer, and Graph RAG share the same checks.</p><h2 id="endpoint-security" tabindex="-1">Endpoint Security <a class="header-anchor" href="#endpoint-security" aria-label="Permalink to &quot;Endpoint Security&quot;">​</a></h2><ul><li><strong>HTTPS by default</strong>: Remote endpoints require HTTPS; loopback addresses (<code>localhost</code>, <code>127.0.0.1</code>, <code>::1</code>) may use HTTP</li><li><strong>Explicit override</strong>: Non-local HTTP requires the explicit <code>MNEME_ALLOW_INSECURE_HTTP=1</code> override</li><li><strong>Client refresh</strong>: Graph RAG caches are bound to the current API key and base URL so endpoint changes take effect immediately</li></ul><h2 id="document-safeguards" tabindex="-1">Document Safeguards <a class="header-anchor" href="#document-safeguards" aria-label="Permalink to &quot;Document Safeguards&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td>Document size limit</td><td>50 MiB (<code>52428800</code>)</td><td>Prevents accidental indexing of huge files</td></tr><tr><td>PDF page limit</td><td>2000 pages</td><td>Caps extraction time and memory</td></tr><tr><td>Document root</td><td>Optional (<code>MNEME_DOCUMENT_ROOT</code>)</td><td>Restricts indexing to a specific directory tree</td></tr><tr><td><code>.env</code> rejection</td><td>Always</td><td>Prevents API keys from being indexed</td></tr></tbody></table><h2 id="context-boundaries" tabindex="-1">Context Boundaries <a class="header-anchor" href="#context-boundaries" aria-label="Permalink to &quot;Context Boundaries&quot;">​</a></h2><p>Retrieved text is placed inside an explicit untrusted-document boundary:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Source: report.pdf] [Citation: S1]</span></span>
<span class="line"><span>&lt;untrusted_document chunk_id=&quot;source-a_chunk_3&quot;&gt;</span></span>
<span class="line"><span>Retrieved text ...</span></span>
<span class="line"><span>&lt;/untrusted_document&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The model is instructed to treat that section as data, not as instructions. Even if a document contains text such as &quot;ignore previous instructions,&quot; it remains inside the untrusted-document region.</p><h3 id="context-truncation-safety" tabindex="-1">Context Truncation Safety <a class="header-anchor" href="#context-truncation-safety" aria-label="Permalink to &quot;Context Truncation Safety&quot;">​</a></h3><p>Context length is bounded (default: 60,000 characters). Mneme truncates only <code>document_text</code>, preserving the complete source marker, citation, and opening/closing boundary. A chunk is skipped when the complete safety frame cannot fit. A safety boundary is not the first thing sacrificed under a tight budget.</p><h2 id="cache-safety" tabindex="-1">Cache Safety <a class="header-anchor" href="#cache-safety" aria-label="Permalink to &quot;Cache Safety&quot;">​</a></h2><ul><li>Graph RAG caches use <strong>schema-validated atomic JSON</strong> rather than loading pickle</li><li>A cache must match the current index fingerprint and manifest version</li><li>Legacy <code>.pkl</code> files are invalidated without being loaded</li></ul><h2 id="data-disclosure" tabindex="-1">Data Disclosure <a class="header-anchor" href="#data-disclosure" aria-label="Permalink to &quot;Data Disclosure&quot;">​</a></h2><p>Indexing and retrieval run locally, but retrieved document snippets are sent to the configured endpoint when Mneme performs query decomposition, Graph RAG entity extraction, or answer generation. The onboarding wizard discloses this explicitly.</p>`,16)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
